import type { RedboxExtension } from '@researchdatabox/redbox-core/extensions';

export function registerRedboxExtension(): RedboxExtension {
  return {
    apiVersion: 1,
    forms: {
      'institution-1.0-draft': {
        name: 'institution-1.0-draft', type: 'rdmp', fields: [],
      },
    },
  };
}

import type { RequestHandler } from '@researchdatabox/redbox-core/extensions';
import { sendApiErrors } from '@researchdatabox/redbox-core/http/express';
import { RequestChronicleHelper } from '@researchdatabox/redbox-core/dist/utilities/RequestChronicle';

export const reportFailure: RequestHandler = (req, res) => {
  const chronicle = RequestChronicleHelper.existing(req);
  chronicle?.addInfo({ reportName: 'institution-report', reportPagingRows: 0 });
  chronicle?.addError(new Error('Report operation failed'));
  sendApiErrors(req, res, 500, [{ code: 'report-failed', title: 'Report failed' }]);
};

import { createFigshareBindings, type CrosswalkResolver }
  from '@researchdatabox/redbox-core/dist/integrations/figshare/bindings';

export async function resolveExampleCrosswalk(crosswalk: CrosswalkResolver) {
  const bindings = createFigshareBindings({ crosswalk, log: { warn() {} } });
  return bindings.resolveCrosswalkBinding({
    kind: 'crosswalk', crosswalkId: 'reviewed-crosswalk',
    sourceVocabularyId: 'institution-vocabulary', outputs: 'categoryId',
    source: { kind: 'path', path: 'codes' },
  }, { codes: ['a'] }, { brandId: 'institution', record: {} });
}

import { convertLegacyDashboardConfiguration, type LegacyCaptureInput }
  from '@researchdatabox/redbox-core/dashboards';

export function previewDashboardMigration(input: LegacyCaptureInput) {
  return convertLegacyDashboardConfiguration(input);
}

